    const boxes = g(/\b(\d+)\/\d+\s*ct\b/i);
    const lb = g(/([\d.]+)\s*lbs?\b/i);
    const oz = g(/([\d.]+)\s*(?:fl\.?\s*)?oz\b/i);
    const ct = g(/([\d,]+)[\s-]*(?:count|ct|pack|pk|pods)\b/i);
    if (sheets && rolls)
      return [money2(price / (sheets * rolls) * 100), "100 sheets"];
    if (boxes)
      return [money2(price / boxes), "box"];
    if (lb)
      return [money2(price / lb), "lb"];
